/* Permanent recipe library; local search and favorites, original six-serving quantities. */
let kitchenQuery='',kitchenScope='edition',kitchenQuick=false,kitchenSavedOnly=false;
let kitchenLibrary=[],kitchenLoading=false,kitchenLoadError=false;
const kitchenFavorites=new Set((()=>{try{const saved=JSON.parse(localStorage.getItem('jr-kitchen-favorites')||'[]');return Array.isArray(saved)?saved:[]}catch{return []}})());
const kitchenKey=r=>r._date+'|'+r.title;
function kitchenCatalog(){const edition=KITCHEN_EDITION||DATA.kitchen;const rows=kitchenScope==='library'?kitchenLibrary:(edition?.recipes||FAMILY_RECIPES).map((r,i)=>({...r,_date:edition?.date,_index:i+1}));const terms=kitchenQuery.toLowerCase().trim().split(/\s+/).filter(Boolean);return rows.filter(r=>{const text=[r.title,r.cuisine,r.meal,...r.ingredients.map(i=>i.name)].join(' ').toLowerCase();return terms.every(t=>text.includes(t))&&(!kitchenQuick||r.prep+r.cook<=30)&&(!kitchenSavedOnly||kitchenFavorites.has(kitchenKey(r)))})}
function kitchenTools(){return `<section class="kitchen-tools" aria-label="Find a recipe"><div class="kitchen-tools-heading"><h2>What shall we cook?</h2><button class="text-button" data-kitchen-clear>Clear filters</button></div><div class="kitchen-search"><label>Search by dish or ingredient<input id="kitchen-query" type="search" placeholder="Try chicken, tofu, Japanese…" value="${escapeHTML(kitchenQuery)}"></label><label>Search in<select id="kitchen-scope"><option value="edition" ${kitchenScope==='edition'?'selected':''}>Selected daily edition</option><option value="library" ${kitchenScope==='library'?'selected':''}>All saved recipes</option></select></label></div><div class="kitchen-toggles"><label><input type="checkbox" id="kitchen-quick" ${kitchenQuick?'checked':''}> 30 minutes or less (prep + cook)</label><label><input type="checkbox" id="kitchen-saved" ${kitchenSavedOnly?'checked':''}> My saved recipes</label></div><p class="fine" role="status">${kitchenLoading?'Loading the recipe archive…':kitchenScope==='library'?`${kitchenLibrary.length} archived recipes loaded. `:''}${kitchenLoadError?'Some dates could not load. <button class="listen" data-kitchen-retry>Retry archive</button>':''}Print the complete recipe or choose Save as PDF in the print dialog. Saved recipes stay on this device.</p></section>`}
async function loadKitchenLibrary(){if(kitchenLoading)return;kitchenLoading=true;kitchenLoadError=false;if(location.hash==='#recipes')render();const dates=[...new Set([...(DAILY_HISTORY.recipes||[]),DATA.kitchen?.date].filter(Boolean))];const results=await Promise.allSettled(dates.map(async date=>{const response=await fetch('data/recipes-archive/'+date+'.json');if(!response.ok)throw Error();const e=await response.json();return e.recipes.map((r,i)=>({...r,_date:e.date,_index:i+1}))}));kitchenLibrary=results.filter(r=>r.status==='fulfilled').flatMap(r=>r.value).sort((a,b)=>b._date.localeCompare(a._date));kitchenLoadError=results.some(r=>r.status==='rejected');kitchenLoading=false;if(location.hash==='#recipes')render()}
function recipeActions(r){if(!r._date)return '';return `<div class="recipe-actions"><button class="listen" data-jr-recipe-print="${escapeHTML(kitchenKey(r))}">▧ Print / Save PDF</button><button class="listen" data-kitchen-save="${escapeHTML(kitchenKey(r))}" aria-pressed="${kitchenFavorites.has(kitchenKey(r))}">${kitchenFavorites.has(kitchenKey(r))?'♥ Saved':'♡ Save recipe'}</button></div>`}
let kitchenTyping;
// Update results without replacing the input, its caret or an IME composition.
function updateKitchenSearch(){
 if(location.hash!=='#recipes')return;
 const grid=document.querySelector('.recipe-grid');if(!grid)return;
 const template=document.createElement('template');template.innerHTML=recipes();
 const next=template.content.querySelector('.recipe-grid');
 grid.previousElementSibling.textContent=next.previousElementSibling.textContent;
 grid.replaceWith(next);
 if(typeof currentLanguage!=='undefined'&&currentLanguage!=='en')translatePage();
}
function queueKitchenSearch(){clearTimeout(kitchenTyping);kitchenTyping=setTimeout(updateKitchenSearch,250)}
document.addEventListener('input',event=>{if(event.target.id!=='kitchen-query')return;kitchenQuery=event.target.value;clearTimeout(kitchenTyping);if(!event.isComposing)queueKitchenSearch()});
document.addEventListener('compositionstart',event=>{if(event.target.id==='kitchen-query')clearTimeout(kitchenTyping)});
document.addEventListener('compositionend',event=>{if(event.target.id!=='kitchen-query')return;kitchenQuery=event.target.value;queueKitchenSearch()});
document.addEventListener('change',event=>{const id=event.target.id;if(id==='kitchen-scope'){kitchenScope=event.target.value;if(kitchenScope==='library'&&!kitchenLibrary.length){loadKitchenLibrary();return}}else if(id==='kitchen-quick')kitchenQuick=event.target.checked;else if(id==='kitchen-saved')kitchenSavedOnly=event.target.checked;else return;render()});
document.addEventListener('click',event=>{if(event.target.closest('[data-kitchen-clear]')){kitchenQuery='';kitchenQuick=false;kitchenSavedOnly=false;cuisine='All';meal='All';render();document.querySelector('#kitchen-query')?.focus();return}const save=event.target.closest('[data-kitchen-save]');if(save){const key=save.dataset.kitchenSave;kitchenFavorites.has(key)?kitchenFavorites.delete(key):kitchenFavorites.add(key);try{localStorage.setItem('jr-kitchen-favorites',JSON.stringify([...kitchenFavorites]))}catch{}render()}if(event.target.closest('[data-kitchen-retry]'))loadKitchenLibrary()});

document.addEventListener('click',event=>{const button=event.target.closest('[data-jr-recipe-print]');if(!button)return;const r=kitchenCatalog().find(r=>kitchenKey(r)===button.dataset.jrRecipePrint);if(!r)return;document.querySelector('#jr-print-recipe')?.remove();const sheet=document.createElement('section');sheet.id='jr-print-recipe';sheet.innerHTML=`<h1>James Real · Family Kitchen</h1><p>${escapeHTML(r._date)} · ${escapeHTML(r.cuisine)}</p><h2>${escapeHTML(r.title)}</h2><p>Serves 6 · Prep ${r.prep} min · Cook ${r.cook} min</p><h3>Ingredients</h3><ul>${r.ingredients.map(i=>`<li>${escapeHTML(i.name)} — ${escapeHTML(i.amount)}</li>`).join('')}</ul><h3>Method</h3><ol>${r.steps.map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ol><p>${escapeHTML(r.note)}</p><p>Allergens: ${escapeHTML(r.allergens)}</p><p>${escapeHTML(r.storage||'')}</p>`;document.body.append(sheet);document.body.classList.add('jr-printing-recipe');window.print();document.body.classList.remove('jr-printing-recipe');sheet.remove()});
